import{z as s,x as o,o as e,c as d,q as t,j as r,D as a,d as B,s as l,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"指数再平衡的效应","description":"","frontmatter":{"title":"指数再平衡的效应","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/etf-rebalance-effects.md","filePath":"quant/etf-rebalance-effects.md","lastUpdated":1791413859000}'),p={name:"quant/etf-rebalance-effects.md"};function F(m,E,c,f,h,u){const n=o("Mermaid");return e(),d("div",null,[E[2]||(E[2]=t('<h1 id="指数再平衡的效应" tabindex="-1">指数再平衡的效应 <a class="header-anchor" href="#指数再平衡的效应" aria-label="Permalink to &quot;指数再平衡的效应&quot;">​</a></h1><div class="epigraph"><p>指数基金一年里最大的一笔交易，不是任何投资决策，而是编制规则在半年前就写好的那一行日历。</p><footer>—— 据 Madhavan, Financial Analysts Journal, 2003（罗素重构）与指数公司调整公告口径整理</footer></div><p><a href="/quant/etf-tracking-error">上一课</a>把事件成本列为跟踪差异的一项；最大、且生效前一年就可预告的事件，是指数自己的定期调整。缺口是持有人视角：这笔强制交易由谁执行、按什么价、成本落在谁的净值里。调整作为套利对象的一面——宣布日到生效日的抢跑与冲击——<a href="/quant/index-rebalance-arb">指数调仓套利</a>与<a href="/quant/index-inclusion-passive-flow">指数纳入与被动流</a>已经写透；本课写产品这一侧的账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>定期调整生成两类强制订单。换样：买入调入、卖出调出。再定标：权重上限、行业配额、自由流通口径调整触发的加减仓，不换样也发生。基金的义务在生效日收盘前把持仓对齐新权重，目标完全公开：\\(\\sum_i |w_i^{\\mathrm{new}} - w_i^{\\mathrm{old}}|\\) 就是单边换手的下限，缓冲带（<a href="/quant/etf-index-construction">第一课</a>）决定了它比「全体排名重排」小多少。效应分三段：宣布日，套利者与预期者建仓，价格先动；生效日，被动产品的需求集中在收盘竞价释放；生效后，临时冲击回吐，对应基金将长期持有的永久部分留下。问题在于：这两段的分界不在公告里，而在稀缺性——弹性资本的供给决定回吐多少。</p><p><span class="marginnote">数字实例：某指数调出一只权重 1.5% 的股票，跟踪该指数的产品合计 2000 亿，则生效日收盘前的被动卖单约有 30 亿；若该股日均成交只有 10 亿，被动流就是 3 倍 ADV——冲击可想而知。换手下限可直接用新旧权重差乘产品规模算出。</span></p><p><span class="marginnote">罗素 2000 重构是这一现象的标准样本：Madhavan（2003）记录了生效日收盘竞价中成交量的极端集中与价格的暂时性跳动；Chen、Noronha 与 Singal（2004）用标普调整证明调入效应中有一块不回吐。两篇合起来就是「临时 vs 永久」分解的出处。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>基金的执行是一条谱。端点一：生效日收盘全额成交——跟踪风险为零，但与全部被动同行挤同一个竞价，冲击成本最高。端点二：提前数日渐进完成——执行价更好，但对新权重的偏离构成主动风险，吃的是 TE 预算。实务取中间：换样腿提前渐进，竞价腿留在生效日收盘。预算怎么分，取决于基金规模对成分 ADV 的占比与 TE 合同的松紧。再定标腿（capping 触发的减持）常被忽略，它的规模可以从新旧权重文件直接算出，是提前可排程的流水线作业。</p><p><span class="marginnote">直觉类比：执行谱像赶高峰的两种走法——跟着人潮挤终点前的最后一班车（生效日收盘竞价），肯定到但最挤；或提前几站下车走路（提前渐进），舒坦但可能「迟到」（偏离新权重的跟踪风险）。预算怎么分，看迟到的罚金多重。</span></p>',10)),(e(),r(i,null,{default:a(()=>[l(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANN%5B%22%E5%AE%A3%E5%B8%83%E6%97%A5%EF%BC%9A%E5%90%8D%E5%8D%95%E4%B8%8E%E6%9D%83%E9%87%8D%E6%96%87%E4%BB%B6%E5%85%AC%E5%B8%83%22%5D%20--%3E%20PRE%5B%22%E9%A2%84%E6%9C%9F%E4%B8%8E%E6%8A%A2%E8%B7%91%EF%BC%9A%E4%BB%B7%E6%A0%BC%E5%85%88%E5%8A%A8%22%5D%0A%20%20ANN%20--%3E%20PLAN%5B%22%E5%9F%BA%E9%87%91%E6%8E%92%E7%A8%8B%EF%BC%9A%E6%8D%A2%E6%89%8B%E9%A2%84%E7%AE%97%E4%B8%8E%E6%B8%90%E8%BF%9B%E7%AA%97%E5%8F%A3%22%5D%0A%20%20PLAN%20--%3E%20EFF%5B%22%E7%94%9F%E6%95%88%E6%97%A5%EF%BC%9A%E8%A2%AB%E5%8A%A8%E9%9C%80%E6%B1%82%E9%9B%86%E4%B8%AD%E9%87%8A%E6%94%BE%22%5D%0A%20%20EFF%20--%3E%20MOC%5B%22%E6%94%B6%E7%9B%98%E7%AB%9E%E4%BB%B7%EF%BC%9A%E9%9B%B6%E8%B7%9F%E8%B8%AA%E9%A3%8E%E9%99%A9%E3%80%81%E6%9C%80%E9%AB%98%E6%8B%A5%E6%8C%A4%22%5D%0A%20%20EFF%20--%3E%20TMP%5B%22%E4%B8%B4%E6%97%B6%E5%86%B2%E5%87%BB%EF%BC%9A%E7%94%9F%E6%95%88%E5%90%8E%E5%9B%9E%E5%90%90%22%5D%0A%20%20EFF%20--%3E%20PERM%5B%22%E6%B0%B8%E4%B9%85%E9%83%A8%E5%88%86%EF%BC%9A%E8%A2%AB%E5%8A%A8%E9%95%BF%E6%9C%9F%E6%8C%81%E6%9C%89%22%5D%0A%20%20PLAN%20--%3E%20ALT%5B%22%E6%9B%BF%E4%BB%A3%EF%BC%9A%E6%8F%90%E5%89%8D%E6%B8%90%E8%BF%9B%EF%BC%8C%E8%8A%B1%20TE%20%E9%A2%84%E7%AE%97%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"效应的强度由被动规模与需求刚性决定：跟踪误差约束把需求弹性压到接近零，被动买盘不看价格，弹性全靠套利资本供给。这也解释了效应为什么不消失——被动份额仍在增长——以及为什么早年的冲击系数不能直接外推：拥挤使抢跑者互相吃利润，观察到的宣布日效应里预期部分越来越大、可交易部分越来越小。对持有人，真正的账是执行缺口：成交价相对生效日收盘基准的差，加上市场冲击中由基金自己买单的那部分。把「指数没输、基金输了」的年度落后归因到管理能力，是再平衡研究里最常见的归因错误。",-1)),(e(),r(i,null,{default:a(()=>[l(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20BENCH%5B%22%E5%9F%BA%E5%87%86%3A%20%E7%94%9F%E6%95%88%E6%97%A5%E6%94%B6%E7%9B%98%E6%96%B0%E6%9D%83%E9%87%8D%E4%BB%B7%22%5D%20--%3E%20GAP%5B%22%E6%89%A7%E8%A1%8C%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20FILL%5B%22%E5%AE%9E%E9%99%85%E6%88%90%E4%BA%A4%E4%BB%B7%22%5D%20--%3E%20GAP%0A%20%20IMP%5B%22%E5%B8%82%E5%9C%BA%E5%86%B2%E5%87%BB%3A%20%E8%A2%AB%E5%8A%A8%E5%90%8C%E8%A1%8C%E4%BA%92%E7%9B%B8%E6%8A%AC%E4%BB%B7%22%5D%20--%3E%20GAP%0A%20%20TIM%5B%22%E6%8B%A9%E6%97%B6%E5%81%8F%E7%A6%BB%3A%20%E6%8F%90%E5%89%8D%E6%B8%90%E8%BF%9B%E7%9A%84%E4%B8%BB%E5%8A%A8%E9%A3%8E%E9%99%A9%22%5D%20--%3E%20GAP%0A%20%20GAP%20--%3E%20WHO%5B%22%E7%BC%BA%E5%8F%A3%E8%90%BD%E5%9C%A8%E5%9F%BA%E9%87%91%E5%87%80%E5%80%BC%E9%87%8C%22%5D%0A%20%20ATTR%5B%22%E5%BD%92%E5%9B%A0%E9%94%99%E8%AF%AF%3A%20%E6%8A%8A%E7%BC%BA%E5%8F%A3%E5%BD%93%E6%88%90%E7%AE%A1%E7%90%86%E8%83%BD%E5%8A%9B%E5%B7%AE%22%5D%20-.-%3E%20WHO%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不设计抢跑策略，那是<a href="/quant/index-rebalance-arb">指数调仓套利</a>的主题；因子宇宙与回填偏差见<a href="/quant/index-rebalance">指数调入调出</a>。也不把效应写成常数：临时与永久的比例随被动规模、衍生品对冲可得性与借券市场变化，事件研究必须分期重估。ETF 层面还有一条间接通道：申赎流把调整需求分散到生效前的数日（PCF 提前变更），使二级市场的冲击形态与基金持仓的执行时点不完全重合——把生效日当成唯一事件日的研究，会漏掉这一段。</p><p><span class="marginnote">常见误区：把生效日当成唯一的事件日。ETF 的申赎清单（PCF）提前数日就变了，套利与做市的需求分散在生效前几天；只盯生效日收盘做事件研究，会漏掉一段已经发生的冲击。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>定期调整生成换样与再定标两类强制订单，单边换手下限是 \\(\\sum_i |w_i^{\\mathrm{new}} - w_i^{\\mathrm{old}}|\\)。</li><li>效应三段：宣布日预期、生效日集中释放、生效后临时回吐与永久保留；分界由弹性资本供给决定。</li><li>执行是一条谱：生效日收盘零跟踪风险但最拥挤，提前渐进省钱但花 TE 预算。</li><li>对持有人的真实账是执行缺口；把「指数赢、基金输」归因于管理能力是常见错误。</li><li>出处：Madhavan, <em>Financial Analysts Journal</em>, 2003；Chen, Noronha and Singal, <em>Journal of Finance</em>, 2004；Petajisto, <em>Financial Analysts Journal</em>, 2011；策略面见<a href="/quant/index-rebalance-arb">指数调仓套利</a>。</li></ul>',5))])}const _=s(p,[["render",F]]);export{D as __pageData,_ as default};
